'use strict';

/**
* Evaluate the factorial function as a single-precision floating-point number.
*
* @module @stdlib/math/base/special/factorialf
*
* @example
* var factorialf = require( '@stdlib/math/base/special/factorialf' );
*
* var v = factorialf( 3.0 );
* // returns 6.0
*
* v = factorialf( -1.5 );
* // returns ~-3.545
*
* v = factorialf( -0.5 );
* // returns ~1.772
*
* v = factorialf( 0.5 );
* // returns ~0.886
*
* v = factorialf( -10.0 );
* // returns NaN
*
* v = factorialf( 34.0 );
* // returns ~2.952e38
*
* v = factorialf( 35.0 );
* // returns Infinity
*
* v = factorialf( NaN );
* // returns NaN
*/

// MODULES //

var main = require( './main.js' );


// EXPORTS //

module.exports = main;
